use strict; use warnings;
my $BIN = "/workspace/dataset/test13_executable";

sub up   { my $s=shift; $s =~ tr/\x61-\x7a/\x41-\x5a/; return $s }
sub down { my $s=shift; $s =~ tr/\x41-\x5a/\x61-\x7a/; return $s }
sub cap  { my $s=shift; return "" if $s eq ""; return up(substr($s,0,1)) . down(substr($s,1)) }

sub hex_of { join(" ", map { sprintf("%02x",ord) } split //, shift) }

# run binary, return (l11,l12,l13) using tail-counting so embedded \n is safe
sub run3 {
  my $W = shift;
  my @cmd = ($BIN, $W);
  my $pid = open(my $fh, "-|") or do { exec { $BIN } ($BIN, $W); die "exec: $!" };
  local $/; my $out = <$fh>; close($fh);
  $out = "" unless defined $out;
  my $n = ($W =~ tr/\n//);          # newlines inside W
  my $per = 1 + $n;                  # physical lines per logical line 11..13
  die "no trailing newline" unless $out =~ /\n\z/;
  my $body = $out; $body =~ s/\n\z//;
  my @phys = split(/\n/, $body, -1);
  my $need = 3*$per;
  die "too few phys lines (".scalar(@phys).") for W=".hex_of($W) if @phys < $need;
  my @tail = @phys[$#phys-$need+1 .. $#phys];
  my @res;
  for my $i (0..2) { push @res, join("\n", @tail[$i*$per .. $i*$per+$per-1]); }
  return @res;
}

my $fails = 0; my $tested = 0;
my @rows;
for my $b (1..255) {
  my $W = "a" . chr($b) . "z";
  my ($l11,$l12,$l13) = run3($W);
  my ($e11,$e12,$e13) = (up($W), down($W), cap($W));
  $tested++;
  for my $t ([11,$l11,$e11],[12,$l12,$e12],[13,$l13,$e13]) {
    if ($t->[1] ne $t->[2]) {
      $fails++;
      printf("MISMATCH byte=0x%02x line=%d  got=[%s] want=[%s]\n", $b, $t->[0], hex_of($t->[1]), hex_of($t->[2]));
    }
  }
}
printf("middle-byte sweep: tested %d bytes (0x01-0xFF), mismatches=%d\n", $tested, $fails);
