// ============================================================================
// NOTATION USED IN THE EVIDENCE ROWS BELOW:
//   Bytes inside printable ASCII (0x20..0x7E) are shown literally.
//   Every other byte is shown as \xHH (uppercase hex). A literal backslash
//   would be shown as \\ (none occurs in the rows). An empty output field
//   means a zero-length string was printed (followed by the '\n' from endl).
//   Args shown with \xHH were passed via bash ANSI-C quoting, e.g. $'caf\xC3\xA9',
//   and every byte was re-verified with `od -An -tx1`.
// ============================================================================
//
// MODEL: all three functions are PURE, STATELESS, BYTE-ORIENTED, ASCII-ONLY
// case mappings over the raw bytes of the argument. There is NO UTF-8
// awareness, NO locale awareness, NO word/whitespace/delimiter awareness,
// NO trimming, and NO length change -- ever.
//
// Exactly 52 of the 255 passable byte values are ever touched:
// 0x41..0x5A (A-Z) by downcase, and 0x61..0x7A (a-z) by upcase.
// All 203 other passable bytes (0x01..0x40, 0x5B..0x60, 0x7B..0xFF) are
// copied through byte-for-byte, INCLUDING every byte 0x80..0xFF, which is
// why UTF-8 continuation/lead bytes survive untouched.

FUNCTION ascii_upper_byte(b : uint8) -> uint8:
    IF b >= 0x61 AND b <= 0x7A THEN          // 'a'..'z'
        RETURN (uint8)(b - 0x20)
    ELSE
        RETURN b                              // identity for ALL other bytes
    END IF

FUNCTION ascii_lower_byte(b : uint8) -> uint8:
    IF b >= 0x41 AND b <= 0x5A THEN          // 'A'..'Z'
        RETURN (uint8)(b + 0x20)
    ELSE
        RETURN b                              // identity for ALL other bytes
    END IF


// ---------------------------------------------------------------- line 11 ---
FUNCTION upcase(s : byte_string) -> byte_string:
    n   = length_in_bytes(s)                  // byte count, NOT character count
    out = new byte_string of exactly n bytes
    FOR i = 0 TO n - 1:
        out[i] = ascii_upper_byte(s[i])       // each byte independent; no context
    END FOR
    RETURN out                                // length(out) == length(s) always


// ---------------------------------------------------------------- line 12 ---
FUNCTION downcase(s : byte_string) -> byte_string:
    n   = length_in_bytes(s)
    out = new byte_string of exactly n bytes
    FOR i = 0 TO n - 1:
        out[i] = ascii_lower_byte(s[i])       // each byte independent; no context
    END FOR
    RETURN out                                // length(out) == length(s) always


// ---------------------------------------------------------------- line 13 ---
FUNCTION capitalize(s : byte_string) -> byte_string:
    n = length_in_bytes(s)
    IF n == 0 THEN
        RETURN ""                             // empty in -> empty out
    END IF
    out    = new byte_string of exactly n bytes
    out[0] = ascii_upper_byte(s[0])           // FIRST BYTE (index 0), not first
                                              // character, not first letter,
                                              // not first non-space
    FOR i = 1 TO n - 1:
        out[i] = ascii_lower_byte(s[i])       // EVERY remaining byte lowercased
    END FOR
    RETURN out

// Exactly equivalent formulation, also fully consistent with all observations:
//     capitalize(s) == upcase(substr(s, 0, 1)) CONCAT downcase(substr(s, 1))
// (Whether the binary literally composes them this way is UNOBSERVABLE.)


// ============================== INVARIANTS PROVEN ============================
// I1. LENGTH: length(upcase(s)) == length(downcase(s)) == length(capitalize(s))
//     == length(s), for every input probed (incl. all 65025 two-byte inputs and
//     4000-byte inputs). No byte is ever inserted, dropped, or expanded --
//     so no 'ß'->"SS", no 'ﬁ'->"FI", no Turkish 'i'->'İ' expansion.
// I2. CONTEXT-FREEDOM: for upcase/downcase the output byte at index i depends
//     ONLY on s[i]. For capitalize it depends only on s[i] and on whether
//     i == 0. Proven by the COMPLETE 2-byte space plus 3-byte alphabet sweep.
// I3. ONLY-LETTERS-MOVE: empirically derived single-byte mapping tables contain
//     exactly 26 non-identity entries each and nothing else:
//       upcase   : 61->41 62->42 ... 7A->5A   (26 entries, all a-z)
//       downcase : 41->61 42->62 ... 5A->7A   (26 entries, all A-Z)
//       capitalize (1-byte input, i.e. index 0 only): 61->41 ... 7A->5A
//     Every one of the other 229 passable bytes maps to itself.
// I4. IDEMPOTENT: f(f(s)) == f(s) for all three (0 failures / 300 random
//     8-byte strings each). Follows from I3 since the images are disjoint from
//     the domains.
// I5. NO TRIMMING / NO WORD LOGIC: leading and trailing spaces, tabs, CRs and
//     newlines are preserved verbatim; capitalize does NOT skip leading
//     whitespace ('  lead' -> '  lead') and does NOT re-capitalize after a
//     space, '_' or '-' ('A B' -> 'A b', 'MiXeD_CaSe-99' -> 'Mixed_case-99').
// I6. NO LOCALE: identical output bytes under LC_ALL/LANG/LC_CTYPE = C,
//     C.UTF-8, en_US.UTF-8, tr_TR.UTF-8, de_DE.UTF-8. In particular
//     upcase('i') == 'I' (0x69 -> 0x49) even under tr_TR.UTF-8 -- never
//     0xC4 0xB0 ('İ') -- and 0xC3 0xA9 ('é') / 0xC3 0x89 ('É') never change.
// I7. NO UTF-8 AWARENESS: a multibyte first character is NOT titlecased;
//     capitalize($'\xC3\xA9ABC') == $'\xC3\xA9abc' (lead byte 0xC3 is merely
//     run through ascii_upper_byte, which is the identity), NOT 'ÉABC'.
